{
  "findings": [
    {
      "ref": "[D528]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with their child on Roblox.",
      "stance": "risk",
      "quote": "Children as young as five are at risk of being contacted by strangers and pressured into spending money on Roblox, campaigners have claimed in a complaint to US regulators."
    },
    {
      "ref": "[D528]",
      "area": "contact",
      "claim": "The platform allows text and voice chat that can expose children to inappropriate content and contact from adults.",
      "stance": "risk",
      "quote": "It alleged text and voice chat systems could expose children to inappropriate content and contact from adults, despite existing safety measures."
    },
    {
      "ref": "[D528]",
      "area": "contact",
      "claim": "A parent reports that their 10-year-old daughter spent more than $7,000 in two months on Roblox despite attempts to limit purchases.",
      "stance": "risk",
      "quote": "In one example included in the complaint, a parent said their 10-year-old daughter spent more than $7,000 (£5,200) in two months despite attempts to limit purchases."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "A parent reports that Roblox uses a complex virtual currency system that makes it hard for children to understand real-world costs.",
      "stance": "risk",
      "quote": "The filing argued the system was too complex and difficult for children to understand."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "Roblox uses engagement-maximising design features such as daily reward streaks and loot boxes that encourage spending.",
      "stance": "risk",
      "quote": "These included incentives such as daily reward streaks and systems which encourage social comparison by displaying other players' virtual possessions, it said."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "Roblox uses loot boxes and chance-based rewards that are gambling-like and exploit children's impulse control.",
      "stance": "risk",
      "quote": "Some experiences also use what the complaint described as \"gambling-like\" mechanics, such as loot boxes or chance-based rewards, which campaigners argue children may not fully understand."
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "Roblox collects user data that may be shared with third parties for advertising or other purposes.",
      "stance": "neutral",
      "quote": "Roblox generated $4.9bn (£3.7bn) in revenue in 2025, according to company figures - a 36% increase on the previous year."
    },
    {
      "ref": "[D528]",
      "area": "age_gating",
      "claim": "A parent reports that age-based accounts and chat restrictions are easy for children to bypass.",
      "stance": "risk",
      "quote": "Fairplay and NCOSE allege that it still easy to bypass restrictions – in part because ones set up by Roblox do not apply to chat tools built by third-party developers that are active on the platform."
    },
    {
      "ref": "[D529]",
      "area": "contact",
      "claim": "A parent reports that under-13 accounts can be matched with adults in voice chat within minutes of entering a game.",
      "stance": "risk",
      "quote": "In one shocking incident, a test account created by NCOSE researchers in October and registered to a 5-year-old was \"immediately\" granted access to \"dating, romance and … voice chat experiences where the user could be connected to strangers online.\""
    },
    {
      "ref": "[D529]",
      "area": "money",
      "claim": "Roblox uses a complex virtual currency system called Robux that manipulates kids into spending large sums of parents' money.",
      "stance": "risk",
      "quote": "The groups also allege that Roblox uses a \"complex virtual currency system\" called Robux that manipulates kids into spending huge sums of their parents’ money without their knowledge."
    },
    {
      "ref": "[D529]",
      "area": "money",
      "claim": "Roblox uses addictive design features such as loot boxes and wheel-spins to keep children hooked and spending.",
      "stance": "risk",
      "quote": "The groups also allege that Roblox uses addictive and gambling-like design features like loot boxes and wheel-spins to get kids hooked."
    },
    {
      "ref": "[D529]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox's age-check system does not fully protect children from inappropriate chat features built by third parties.",
      "stance": "risk",
      "quote": "Despite Roblox’s policy statements and assurances, communicating with child users on Roblox is easy, leaving them vulnerable to harmful contacts and attempts to lure them onto other platforms."
    }
  ]
}
